import { useEffect, useState } from 'react';
import Head from 'next/head';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { supabase } from '../config/supabase';

export default function Projetos() {
  const [projetos, setProjetos] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProjetos = async () => {
      const { data, error } = await supabase
        .from('projetos')
        .select('*')
        .order('criado_em', { ascending: false });
      
      if (!error) setProjetos(data);
      setLoading(false);
    };

    fetchProjetos();
  }, []);

  return (
    <>
      <Head>
        <title>Projetos | Nicolas Almir</title>
        
      </Head>

      <Header />

      <main className="main-content" style={{ minHeight: '80vh', paddingBottom: '4rem' }}>
        <h1 className="page-title" style={{ textAlign: 'center', color: 'var(--primary-color)', marginBottom: '1rem', fontSize: '2.5rem' }}>Meus Projetos</h1>
        <p style={{ textAlign: 'center', color: 'var(--text-secondary-dark)', marginBottom: '3rem' }}>O que eu ando construindo.</p>

        {loading ? (
          <p style={{ textAlign: 'center', color: 'var(--primary-color)' }}>Carregando dados da Matrix...</p>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))', gap: '2rem' }}>
            {projetos.map(proj => (
              <div key={proj.id} style={{ backgroundColor: 'var(--surface-dark)', borderRadius: '8px', padding: '1.5rem', border: '1px solid var(--secondary-color)', transition: 'transform 0.3s', cursor: 'pointer' }} onMouseOver={e => e.currentTarget.style.transform = 'translateY(-5px)'} onMouseOut={e => e.currentTarget.style.transform = 'translateY(0)'}>
                <h3 style={{ color: 'white', marginBottom: '1rem' }}>{proj.titulo}</h3>
                <p style={{ color: '#a1a1a1', fontSize: '0.9rem', marginBottom: '1.5rem', lineHeight: '1.6' }}>{proj.descricao}</p>
                
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem', marginBottom: '1.5rem' }}>
                  {proj.tecnologias.map((tech, index) => (
                    <span key={index} style={{ backgroundColor: 'rgba(0, 255, 65, 0.1)', color: 'var(--primary-color)', padding: '0.3rem 0.8rem', borderRadius: '20px', fontSize: '0.8rem', border: '1px solid var(--secondary-color)' }}>
                      {tech}
                    </span>
                  ))}
                </div>

                <a href={proj.link_github} target="_blank" rel="noopener noreferrer" className="btn secondary" style={{ width: '100%', display: 'flex', justifyContent: 'center', gap: '0.5rem', alignItems: 'center' }}>
                  <i className="fab fa-github"></i> Ver Código
                </a>
              </div>
            ))}
            
            {projetos.length === 0 && (
              <p style={{ gridColumn: '1 / -1', textAlign: 'center', color: '#a1a1a1' }}>Nenhum projeto cadastrado ainda.</p>
            )}
          </div>
        )}
      </main>

      <Footer />
    </>
  );
}
